curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'incident' in ch['name'].lower():
            print(f\"ID: {ch['id']}, Name: {ch['name']}, Topic: {ch.get('topic', {}).get('value', 'N/A')}\")
else:
    print('Error:', data)
"

curl -s -X POST "https://slack.com/api/users.list" -d "token=<TOKEN>&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if 'aisha' in u.get('real_name', '').lower() or 'aisha' in u.get('profile', {}).get('display_name', '').lower():
            print(f\"ID: {u['id']}, Name: {u['real_name']}, Username: {u.get('username', 'N/A')}\")
else:
    print('Error:', data)
"
